  let l = await get(base, "?page=2");
  assert.deepEqual([l.items.length, l.total, l.page], [2, 12, 2]);
  assert.equal(l.items[0].id, ids[10]);
  l = await get(base, "?tag=PAR&limit=4&page=2");
  assert.deepEqual([l.items.length, l.total], [2, 6]);
  await req(base, `/api/tasks/${ids[1]}`, "PATCH", { done: true });
  assert.equal((await get(base, "?tag=par&done=false")).total, 5);
  assert.equal((await get(base, "?page=99")).items.length, 0);
  for (const q of ["page=0", "page=x", "limit=0", "limit=51", "done=sim", "overdue=false", "tag="])
    assert.equal((await req(base, "/api/tasks?" + q)).status, 400, q);
}));

