  await post(base, { title: "futura", due: "2999-01-01" });
  await post(base, { title: "sem" });
  await req(base, `/api/tasks/${b.id}`, "PATCH", { done: true });
  const l = await get(base, "?overdue=true");
  assert.deepEqual([l.items.map((t) => t.id), l.total], [[a.id], 1]);
}));
